"use client";

import * as TabsPrimitive from "@radix-ui/react-tabs";
import { createContext, useCallback, useContext, useId, useLayoutEffect, useRef, useState } from "react";
import type { ComponentPropsWithoutRef, ReactNode, RefObject } from "react";
import { ChevronLeft as NavArrowLeft, ChevronRight as NavArrowRight } from "lucide-react";
import { AnimatePresence, LayoutGroup, animate, motion, useReducedMotion } from "motion/react";
import type { AnimationPlaybackControls, Variants } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import { FluidHoverHighlight, useFluidHover } from "../lib/fluid-hover";
import styles from "./tabs.module.css";

type RootProps = ComponentPropsWithoutRef<typeof TabsPrimitive.Root>;
/** `direction` is +1 when the new tab sits after the old one; `panelHeightRef` holds the visible panel height so the next panel can morph from it; `leavingRectRef` pins the outgoing panel where it was on screen. */
const TabsContext = createContext<{ active: string; layoutId: string; direction: number; panelHeightRef: RefObject<number | null>; leavingRectRef: RefObject<DOMRect | null> }>({ active: "", layoutId: "tabs", direction: 1, panelHeightRef: { current: null }, leavingRectRef: { current: null } });

export function Tabs({ value, defaultValue, onValueChange, className, ...props }: RootProps) {
  const [internal, setInternal] = useState(defaultValue ?? "");
  const [direction, setDirection] = useState(1);
  const active = value ?? internal;
  const layoutId = useId();
  const root = useRef<HTMLDivElement>(null);
  const panelHeightRef = useRef<number | null>(null);
  const leavingRectRef = useRef<DOMRect | null>(null);
  function handleChange(next: string) {
    const frame = root.current;
    leavingRectRef.current = frame?.querySelector(':scope > [role="tabpanel"][data-state="active"]')?.getBoundingClientRect() ?? null;
    const order = frame ? Array.from(frame.querySelectorAll<HTMLElement>('[role="tab"][data-value]')).filter(tab => tab.closest(`.${styles.root}`) === frame).map(tab => tab.dataset.value) : [];
    const from = order.indexOf(active), to = order.indexOf(next);
    if (from >= 0 && to >= 0 && from !== to) setDirection(to > from ? 1 : -1);
    if (value === undefined) setInternal(next); onValueChange?.(next);
  }
  return <TabsContext.Provider value={{ active, layoutId, direction, panelHeightRef, leavingRectRef }}><LayoutGroup id={layoutId}><TabsPrimitive.Root {...props} ref={root} className={[styles.root, className].filter(Boolean).join(" ")} value={active} onValueChange={handleChange}/></LayoutGroup></TabsContext.Provider>;
}

export function TabsList({ className, ...props }: ComponentPropsWithoutRef<typeof TabsPrimitive.List>) {
  const { active } = useContext(TabsContext);
  const reduced = useReducedMotion();
  const shell = useRef<HTMLDivElement>(null);
  const viewport = useRef<HTMLDivElement>(null);
  const list = useRef<HTMLDivElement>(null);
  const [edges, setEdges] = useState({ overflow: false, left: false, right: false });
  // Fluid hover: the nearest tab is lit, gaps included. Radix selects on mouse-down, so a gap click stays inert, and focus
  // already shows the selection, so the keyboard leaves the hover fill alone.
  const hover = useFluidHover(list, { items: '[role="tab"]', axis: "x", gapClick: false, followFocus: false });
  const update = useCallback(() => {
    const frame = shell.current;
    const scroll = viewport.current;
    if (!frame || !scroll) return;
    const max = Math.max(0, scroll.scrollWidth - scroll.clientWidth);
    const next = { overflow: scroll.scrollWidth > frame.clientWidth + 1, left: scroll.scrollLeft > 1, right: scroll.scrollLeft < max - 1 };
    setEdges(previous => previous.overflow === next.overflow && previous.left === next.left && previous.right === next.right ? previous : next);
  }, []);
  const reveal = useCallback((tab: HTMLElement | null) => {
    const scroll = viewport.current;
    if (!scroll || !tab) return;
    const frame = scroll.getBoundingClientRect();
    const item = tab.getBoundingClientRect();
    const max = Math.max(0, scroll.scrollWidth - scroll.clientWidth);
    const left = frame.left + (scroll.scrollLeft > 1 ? 34 : 0);
    const right = frame.right - (scroll.scrollLeft < max - 1 ? 34 : 0);
    const delta = item.left < left ? item.left - left : item.right > right ? item.right - right : 0;
    if (delta) scroll.scrollBy({ left: delta, behavior: reduced ? "instant" : "smooth" });
  }, [reduced]);
  useLayoutEffect(() => {
    const frame = shell.current;
    const scroll = viewport.current;
    const content = list.current;
    if (!frame || !scroll || !content) return;
    const observer = new ResizeObserver(update);
    observer.observe(frame);
    observer.observe(scroll);
    observer.observe(content);
    scroll.addEventListener("scroll", update, { passive: true });
    update();
    return () => { observer.disconnect(); scroll.removeEventListener("scroll", update); };
  }, [update]);
  useLayoutEffect(() => { reveal(list.current?.querySelector<HTMLElement>('[role="tab"][data-state="active"]') ?? null); }, [active, reveal]);
  const scrollTabs = (direction: number) => viewport.current?.scrollBy({ left: direction * (viewport.current?.clientWidth ?? 0) * .75, behavior: reduced ? "instant" : "smooth" });
  return <div ref={shell} className={styles.listShell} data-overflow={edges.overflow} data-left={edges.left} data-right={edges.right}>
    {edges.overflow && <button type="button" className={`${styles.scrollButton} ${styles.scrollLeft}`} aria-label="Scroll tabs left" disabled={!edges.left} onClick={() => scrollTabs(-1)}><NavArrowLeft width={17} height={17} aria-hidden="true"/></button>}
    <motion.div ref={viewport} layoutScroll className={styles.viewport} {...hover.handlers} onFocusCapture={event => { if (event.target instanceof HTMLElement && event.target.getAttribute("role") === "tab") reveal(event.target); }}>
      <TabsPrimitive.List {...props} ref={list} className={[styles.list, className].filter(Boolean).join(" ")}>
        <FluidHoverHighlight hover={hover} className={styles.hover}/>
        {props.children}
      </TabsPrimitive.List>
    </motion.div>
    {edges.overflow && <button type="button" className={`${styles.scrollButton} ${styles.scrollRight}`} aria-label="Scroll tabs right" disabled={!edges.right} onClick={() => scrollTabs(1)}><NavArrowRight width={17} height={17} aria-hidden="true"/></button>}
  </div>;
}

export interface TabsTriggerProps extends ComponentPropsWithoutRef<typeof TabsPrimitive.Trigger> {
  /**
   * An icon before the label, such as a 16px Lucide icon. It is sized, coloured with the label (muted, then the active
   * colour when selected) and hidden from screen readers. For an icon-only tab, leave out the label and pass `aria-label`.
   */
  icon?: ReactNode;
}

export function TabsTrigger({ className, children, value, icon, ...props }: TabsTriggerProps) {
  const { active } = useContext(TabsContext);
  const reduced = useReducedMotion();
  // The LayoutGroup in Tabs scopes the highlight to this instance, so it glides between triggers but never flies in from another tab set.
  // An icon with no label is a square tab instead of a text tab's minimum width.
  const iconOnly = !!icon && (children === undefined || children === null || children === false);
  return <TabsPrimitive.Trigger {...props} value={value} data-value={value} data-icon-only={iconOnly || undefined} className={[styles.trigger, className].filter(Boolean).join(" ")}>
    {active === value && <motion.span className={styles.selection} layoutId="selection" layoutDependency={active} transition={reduced ? { duration: 0 } : motionTokens.spring.morph} aria-hidden="true"/>}
    <span className={styles.triggerLabel}>
      {icon ? <span className={styles.icon} aria-hidden="true">{icon}</span> : null}
      {children}
    </span>
  </TabsPrimitive.Trigger>;
}

const panelMotion: Variants = {
  enter: (direction: number) => ({ opacity: 0, x: direction * 8 }),
  center: { opacity: 1, x: 0, transition: { opacity: { duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter] }, x: motionTokens.spring.smooth } },
  exit: (direction: number) => ({ opacity: 0, x: direction * -6, transition: { duration: motionTokens.duration.instant, ease: [...motionTokens.ease.standard] } }),
};
/** Reduced motion: a short crossfade in place. Keys match panelMotion so server and client render identical styles. */
const panelFade: Variants = {
  enter: { opacity: 0, x: 0 },
  center: { opacity: 1, x: 0, transition: { duration: motionTokens.duration.instant } },
  exit: { opacity: 0, x: 0, transition: { duration: motionTokens.duration.instant } },
};

export function TabsContent({ className, value, forceMount, children, ...props }: ComponentPropsWithoutRef<typeof TabsPrimitive.Content>) {
  const { active, direction, panelHeightRef, leavingRectRef } = useContext(TabsContext);
  const reduced = useReducedMotion();
  const panel = useRef<HTMLDivElement>(null);
  const selected = active === value;
  const classes = [styles.content, className].filter(Boolean).join(" ");
  // The incoming panel starts at the outgoing panel's height and settles at its own, so content below glides instead of jumping.
  useLayoutEffect(() => {
    const node = panel.current;
    if (!node || forceMount) return;
    // Outgoing: the tab root may have changed size around it, so pin the panel to where it was while it fades.
    if (!selected) { const before = leavingRectRef.current; const now = node.getBoundingClientRect(); if (before) node.style.translate = `${before.left - now.left}px ${before.top - now.top}px`; node.inert = true; return; }
    node.style.translate = ""; node.inert = false;
    const from = panelHeightRef.current;
    const to = node.offsetHeight;
    let controls: AnimationPlaybackControls | undefined;
    const release = () => { node.style.height = ""; node.style.overflow = ""; };
    if (from !== null && Math.abs(from - to) > 1 && !reduced) {
      if (to > from) node.style.overflow = "clip";
      controls = animate(node, { height: [from, to] }, { ...motionTokens.spring.smooth, onComplete: release });
    }
    panelHeightRef.current = controls && from !== null ? from : to;
    const observer = new ResizeObserver(() => { panelHeightRef.current = node.offsetHeight; });
    observer.observe(node);
    return () => { observer.disconnect(); controls?.stop(); release(); };
  }, [selected, reduced, forceMount, panelHeightRef, leavingRectRef]);
  if (forceMount) return <TabsPrimitive.Content {...props} value={value} forceMount className={classes}>{children}</TabsPrimitive.Content>;
  return <AnimatePresence initial={false} mode="popLayout" custom={direction}>
    {selected && <TabsPrimitive.Content {...props} key={value} value={value} forceMount asChild>
      <motion.div ref={panel} className={classes} custom={direction} variants={reduced ? panelFade : panelMotion} initial="enter" animate="center" exit="exit">{children}</motion.div>
    </TabsPrimitive.Content>}
  </AnimatePresence>;
}

/* Positioned so an outgoing panel pops out exactly where it was while the next one takes its place. */
.root { position: relative; }
.listShell { position: relative; display: inline-flex; max-width: 100%; min-width: 0; align-items: center; isolation: isolate; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-muted); }
.viewport { min-width: 0; overflow-x: auto; border-radius: inherit; corner-shape: inherit; scrollbar-width: none; }
.viewport::-webkit-scrollbar { display: none; }
.listShell[data-left="true"] .viewport { mask-image: linear-gradient(to right, transparent, black 35px, black); }
.listShell[data-right="true"] .viewport { mask-image: linear-gradient(to right, black, black calc(100% - 35px), transparent); }
.listShell[data-left="true"][data-right="true"] .viewport { mask-image: linear-gradient(to right, transparent, black 35px, black calc(100% - 35px), transparent); }
/* The list owns the stacking context so the gliding highlight passes under every label, not over earlier ones. */
.list { position: relative; isolation: isolate; display: inline-flex; width: max-content; align-items: center; gap: var(--space-tight); padding: var(--space-tight); }
.scrollButton { position: absolute; z-index: 2; top: 0; bottom: 0; display: grid; width: 33px; place-items: center; border: 0; background: var(--surface-muted); color: var(--foreground); }
.scrollLeft { left: 0; border-radius: var(--radius-control) 0 0 var(--radius-control); }
.scrollRight { right: 0; border-radius: 0 var(--radius-control) var(--radius-control) 0; }
.scrollButton:disabled { opacity: 0; pointer-events: none; }
.scrollButton:focus-visible { --focus-outline-offset: -3px; }
.trigger { position: relative; -webkit-tap-highlight-color: transparent; display: inline-grid; min-width: 5.5rem; place-items: center; flex: 0 0 auto; min-height: var(--control-height-sm); border: 0; border-radius: calc(var(--radius-control) - var(--space-tight)); padding: 0 var(--space-group); background: transparent; color: var(--text-muted); font: inherit; font-size: var(--text-sm); font-weight: 500; white-space: nowrap; cursor: pointer; transition: color var(--duration-fast) var(--ease-standard); }
@media (hover: hover) and (pointer: fine) { .trigger:hover { color: var(--foreground); } }
.trigger:active { color: var(--foreground); }.trigger[data-state="active"] { color: var(--accent-strong); }
/* The hover fill glides under the tabs and under the selection, so the selected tab never changes on hover. */
.hover { z-index: -1; border-radius: calc(var(--radius-control) - var(--space-tight)); corner-shape: var(--corner-shape); background: color-mix(in oklab, var(--foreground) 5%, transparent); }
.selection { position: absolute; z-index: -1; inset: 0; border: 1px solid var(--border); border-radius: inherit; corner-shape: inherit; background: var(--surface); box-shadow: var(--shadow-resting); will-change: transform; }
.triggerLabel { position: relative; z-index: 1; display: inline-flex; align-items: center; gap: var(--space-related); }
/* An icon before the label: one size for every tab set, coloured with the label so it follows hover and selection. */
.icon { display: inline-grid; flex: none; place-items: center; color: currentColor; }
.icon svg { width: 16px; height: 16px; }
/* Icon-only tabs are square, the height of the strip's controls. */
.trigger[data-icon-only] { min-width: var(--control-height-sm); padding: 0; }
.trigger:disabled { cursor: not-allowed; opacity: .5; }
.content { margin-top: var(--space-inset); color: var(--text-secondary); font-size: var(--text-sm); line-height: var(--leading-body); }
/* The outgoing panel is lifted out of flow by the presence animation; drop its margin so it stays in place and ignore stray clicks. */
.content[data-motion-pop-id] { margin-top: 0; }
.content[data-state="inactive"] { pointer-events: none; }
.content:focus-visible { --focus-outline-offset: 3px; border-radius: var(--radius-control); }
@media (prefers-reduced-motion: reduce) { .trigger { transition: none; } }

"use client";

/**
 * Fluid hover: in a set of items (a menu, a list, tabs, a grid), the item nearest the pointer is lit, even while the
 * pointer is in a gap, the padding or past the last item, and one highlight springs between items. A click in a gap goes
 * to the lit item, so what is lit is what a click hits. A new pointer entry fades the highlight in where it lands instead
 * of sliding it over from the last item. The keyboard moves it without travel, and reduced motion keeps the fade but
 * drops the travel.
 *
 *   const list = useRef<HTMLUListElement>(null);
 *   const hover = useFluidHover(list, { items: "[data-item]" });
 *   <ul ref={list} className={styles.list} {...hover.handlers}>      // .list { position: relative }
 *     <FluidHoverHighlight hover={hover} className={styles.highlight} />
 *     …items…
 *   </ul>
 *
 * Adapted from Fluid Functionalism's use-fluid-hover and fluid-hover-highlight by Micka Touillaud (MIT),
 * https://github.com/mickadesign/fluid-functionalism. Items are found by a selector instead of registering themselves,
 * so a component adopts it without changing its items.
 */
import { useEffect, useEffectEvent, useRef, useState } from "react";
import type { FocusEvent, MouseEvent, PointerEvent, RefObject } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { motionTokens } from "./motion-tokens";

/** An item's box in the container's own layout space (unaffected by transforms or scrolling). */
export interface FluidRect { top: number; left: number; width: number; height: number }

export interface FluidHoverState {
  /** Where the highlight sits, or null when nothing is lit. */
  rect: FluidRect | null;
  /** The lit item. */
  item: HTMLElement | null;
  /** False when the highlight should jump (keyboard, a resize) rather than travel. */
  glide: boolean;
  /** Steps on each new pointer entry, so the highlight fades in where it lands. */
  session: number;
}

export interface FluidHoverOptions {
  /** Selector for the items inside the container. */
  items: string;
  /** "y" for lists (default), "x" for a row of tabs, "xy" for grids. */
  axis?: "x" | "y" | "xy";
  /** Items the highlight skips (and a gap click never activates). Defaults to disabled or aria-disabled items. */
  isItemDisabled?: (item: HTMLElement) => boolean;
  /** "skip" (default) lights the nearest enabled item even over a disabled one; "clear" lights nothing over a disabled item (a calendar's unavailable days). */
  disabled?: "skip" | "clear";
  /** Route a click in a gap to the lit item. On by default; turn it off where empty space should stay inert. */
  gapClick?: boolean;
  /** Light the item that receives keyboard focus. On by default. */
  followFocus?: boolean;
}

const defaultDisabled = (item: HTMLElement) =>
  item.matches(":disabled, [aria-disabled='true'], [data-disabled]");

/** Controls that sit between items keep their own clicks. */
const CONTROL = "input, textarea, select, button, a, summary, [contenteditable], [role='textbox'], [role='searchbox'], [role='button']";

/** The item's box relative to the container, summing offsets through positioned ancestors in between. */
export function rectOf(item: HTMLElement, container: HTMLElement): FluidRect {
  let top = item.offsetTop, left = item.offsetLeft;
  let parent = item.offsetParent as HTMLElement | null;
  while (parent && parent !== container && container.contains(parent)) {
    top += parent.offsetTop + parent.clientTop;
    left += parent.offsetLeft + parent.clientLeft;
    parent = parent.offsetParent as HTMLElement | null;
  }
  return { top, left, width: item.offsetWidth, height: item.offsetHeight };
}

/**
 * The item the pointer is inside, or else the one whose edge is nearest along the axis (both axes for a grid). Edges, not
 * centres, so a gap next to a wide item still lights the item the pointer is closer to.
 */
export function pickNearest(items: HTMLElement[], x: number, y: number, axis: "x" | "y" | "xy"): HTMLElement | null {
  let nearest: HTMLElement | null = null, best = Infinity;
  for (const item of items) {
    const r = item.getBoundingClientRect();
    if (!r.width && !r.height) continue;
    if (x >= r.left && x <= r.right && y >= r.top && y <= r.bottom) return item;
    const dx = Math.max(r.left - x, 0, x - r.right), dy = Math.max(r.top - y, 0, y - r.bottom);
    const distance = axis === "x" ? dx : axis === "y" ? dy : Math.hypot(dx, dy);
    if (distance < best) { best = distance; nearest = item; }
  }
  return nearest;
}

/** Hands a gap click to the item as a real mouse click (detail, modifiers and coordinates kept), so the item reads it as a pointer press, not a keyboard one. */
function forwardClick(item: HTMLElement, event: MouseEvent<HTMLElement>) {
  const { detail, clientX, clientY, screenX, screenY, ctrlKey, shiftKey, altKey, metaKey, button, buttons } = event;
  item.dispatchEvent(new globalThis.MouseEvent("click", { bubbles: true, cancelable: true, composed: true, view: window, detail, clientX, clientY, screenX, screenY, ctrlKey, shiftKey, altKey, metaKey, button, buttons }));
}

/** Whether an event happened inside the element whose handler hears it, not in a portalled child (a submenu, a tooltip). */
const isOwn = (event: { currentTarget: EventTarget; target: EventTarget }) =>
  !(event.currentTarget instanceof Node) || !(event.target instanceof Node) || event.currentTarget.contains(event.target);

export function useFluidHover<T extends HTMLElement>(container: RefObject<T | null>, options: FluidHoverOptions) {
  const { items: selector, axis = "y", isItemDisabled = defaultDisabled, disabled = "skip", gapClick = true, followFocus = true } = options;
  const [state, setState] = useState<FluidHoverState>({ rect: null, item: null, glide: false, session: 0 });
  const current = useRef(state);
  const pointer = useRef(false);
  const entering = useRef(false);
  const frame = useRef(0);

  function commit(next: FluidHoverState) {
    const prev = current.current;
    if (prev.item === next.item && prev.session === next.session && sameRect(prev.rect, next.rect)) return;
    current.current = next;
    setState(next);
  }

  function light(item: HTMLElement | null, glide: boolean) {
    const root = container.current;
    if (!root || !item) return commit({ ...current.current, rect: null, item: null, glide });
    let session = current.current.session;
    if (entering.current) { entering.current = false; session += 1; }
    commit({ rect: rectOf(item, root), item, glide: glide && session === current.current.session, session });
  }

  const enabledItems = () => {
    const root = container.current;
    return root ? [...root.querySelectorAll<HTMLElement>(selector)].filter(item => !isItemDisabled(item)) : [];
  };

  // The lit item can move under a still highlight (a resize, content above it changing): follow it without travel.
  const follow = useEffectEvent(() => { const { item } = current.current; if (item?.isConnected) light(item, false); });
  useEffect(() => {
    const root = container.current;
    if (!root || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => follow());
    observer.observe(root);
    return () => observer.disconnect();
  }, [container]);
  useEffect(() => () => cancelAnimationFrame(frame.current), []);

  const handlers = {
    onMouseEnter: () => { entering.current = true; },
    onMouseMove: (event: MouseEvent<T>) => {
      if (!isOwn(event)) return;
      pointer.current = true;
      const { clientX, clientY } = event;
      cancelAnimationFrame(frame.current);
      frame.current = requestAnimationFrame(() => {
        const over = disabled === "clear" ? document.elementFromPoint(clientX, clientY)?.closest<HTMLElement>(selector) : null;
        light(over && isItemDisabled(over) ? null : pickNearest(enabledItems(), clientX, clientY, axis), true);
      });
    },
    onMouseLeave: () => { cancelAnimationFrame(frame.current); entering.current = false; light(null, false); },
    onKeyDownCapture: () => { pointer.current = false; },
    onFocus: (event: FocusEvent<T>) => {
      if (!followFocus || pointer.current || !isOwn(event)) return;
      const item = event.target instanceof HTMLElement ? event.target.closest<HTMLElement>(selector) : null;
      if (item && container.current?.contains(item) && !isItemDisabled(item)) light(item, false);
    },
    onBlur: (event: FocusEvent<T>) => {
      if (!pointer.current && !event.currentTarget.contains(event.relatedTarget as Node | null)) light(null, false);
    },
    onClick: (event: MouseEvent<T>) => {
      if (!gapClick || !isOwn(event)) return;
      const target = event.target as Element;
      if (!target.isConnected || target.closest(selector) || target.closest(CONTROL)) return;
      const { item } = current.current;
      if (item?.isConnected && !isItemDisabled(item)) forwardClick(item, event);
    },
  };

  /** Clears the highlight at once, such as when a menu opens again. */
  const reset = () => { cancelAnimationFrame(frame.current); entering.current = true; light(null, false); };

  return { ...state, handlers, reset, light };
}

export interface NearestItemOptions extends Omit<FluidHoverOptions, "followFocus"> {
  /** Called with the nearest enabled item as the mouse moves over the container. */
  onPick: (item: HTMLElement) => void;
}

/**
 * Fluid hover's picking without its highlight, for a list that already keeps its own active item and highlight (a listbox
 * with aria-activedescendant, a roving list): the mouse picks the nearest enabled item, gaps and padding included, and a
 * click in a gap goes to that item. Spread the result on the container.
 */
// A hook only so callbacks that touch refs can be passed during render; it keeps no state.
export function useNearestItem<T extends HTMLElement>({ items: selector, axis = "y", isItemDisabled = defaultDisabled, gapClick = true, onPick }: NearestItemOptions) {
  const nearest = (event: MouseEvent<T>) => {
    if (!isOwn(event)) return null;
    const items = [...event.currentTarget.querySelectorAll<HTMLElement>(selector)].filter(item => !isItemDisabled(item));
    return pickNearest(items, event.clientX, event.clientY, axis);
  };
  return {
    onPointerMove: (event: PointerEvent<T>) => { if (event.pointerType !== "mouse") return; const item = nearest(event); if (item) onPick(item); },
    onClick: (event: MouseEvent<T>) => {
      if (!gapClick) return;
      const target = event.target as Element;
      if (!target.isConnected || target.closest(selector) || target.closest(CONTROL)) return;
      const item = nearest(event);
      if (item) forwardClick(item, event);
    },
  };
}

const sameRect = (a: FluidRect | null, b: FluidRect | null) =>
  a === b || (!!a && !!b && a.top === b.top && a.left === b.left && a.width === b.width && a.height === b.height);

export interface FluidHoverHighlightProps {
  /** The state from useFluidHover (or any { rect, glide, session }). */
  hover: Pick<FluidHoverState, "rect" | "glide" | "session">;
  /** Radius, fill, z-index. The container must be position: relative; the highlight is placed at its top-left corner. */
  className?: string;
  /** Extra attributes for styling, such as data-tone. */
  tone?: string;
}

/** The one highlight a fluid hover set renders: it springs between items on transforms, and fades in and out. */
export function FluidHoverHighlight({ hover, className, tone }: FluidHoverHighlightProps) {
  const reduced = useReducedMotion() ?? false;
  const { rect, glide, session } = hover;
  const place = rect ? { x: rect.left, y: rect.top, width: rect.width, height: rect.height } : undefined;
  return (
    <AnimatePresence initial={false}>
      {place ? (
        <motion.span key={session} className={className} data-tone={tone} aria-hidden="true"
          style={{ position: "absolute", top: 0, left: 0, pointerEvents: "none" }}
          initial={{ opacity: 0, ...place }}
          animate={{ opacity: 1, ...place }}
          exit={{ opacity: 0, transition: motionTokens.spring.fast.exit }}
          transition={{ default: glide && !reduced ? motionTokens.spring.fast : { duration: 0 }, opacity: { duration: motionTokens.duration.fast } }} />
      ) : null}
    </AnimatePresence>
  );
}
